import itertools

def solve_task():
    results = {}

    for m in [1, 2, 3]:
        # 1. Calculate coefficients D_k
        D = {}
        for k in range(m + 1):
            # D_k = 7^(k-1) * (6k - 7m + 7)
            if k == 0:
                # 7^(0-1) = 1/7
                D[k] = (1/7) * (6*k - 7*m + 7)
            else:
                D[k] = (7**(k - 1)) * (6*k - 7*m + 7)

        # print(f"--- Case m={m} ---")
        # print(f"D coefficients: {D}")

        # 2. Define search space for digits b_k
        # b_k in {0, 1, ..., 6}
        # b_m must be non-zero: {1, 2, ..., 6}

        # The total tuple size is m+1: (b_0, b_1, ..., b_m)

        # Digits b_0 to b_{m-1} can be 0..6
        digit_range_lower = range(7)
        # Digit b_m can be 1..6
        digit_range_upper = range(1, 7)

        # Generate all combinations of digits (b_0, ..., b_{m-1}, b_m)

        # We iterate over b_m first since it has a unique constraint
        zero_solutions_count = 0

        for b_m in digit_range_upper:
            # Iterate over all combinations of the first m digits (b_0 to b_{m-1})
            # The product generates tuples of length m
            for b_prefix in itertools.product(digit_range_lower, repeat=m):
                # Construct the full digit tuple (b_0, ..., b_{m-1}, b_m)
                b = b_prefix + (b_m,)

                # 3. Calculate the sum S = sum(b_k * D_k)
                S = 0
                for k in range(m + 1):
                    # b[k] is b_k
                    S += b[k] * D[k]

                # 4. Check if S equals zero
                # We must check for near zero due to potential floating point issues with D_0
                if abs(S) < 1e-9:
                    zero_solutions_count += 1

        results[m] = zero_solutions_count
        print(f"For m={m}, the number of solutions found is: {zero_solutions_count}")

    return results

if __name__ == "__main__":
    solve_task()

